mapper.select:
SELECT d.DATA_ID, d.TASK_ID, d.TEMPLATE_ID, d.INDICATOR_ID, d.ORG_ID, d.PERIOD, d.DIMENSION_VALUES, d.DATA_VALUE, d.DATA_SOURCE, d.CELL_COLOR, d.IS_EDITABLE, d.TENANT_ID, d.CREATE_USER, d.CREATE_TIME, d.UPDATE_USER, d.UPDATE_TIME, t.TASK_NAME, tp.TEMPLATE_NAME, i.INDICATOR_NAME, '' AS ORG_NAME FROM TBL_REPORT_DATA d LEFT JOIN TBL_REPORT_TASK t ON d.TASK_ID = t.TASK_ID LEFT JOIN TBL_FORM_TEMPLATE tp ON d.TEMPLATE_ID = tp.TEMPLATE_ID LEFT JOIN TBL_INDICATOR_INFO i ON d.INDICATOR_ID = i.INDICATOR_ID WHERE d.TENANT_ID = #{tenantId}
AND d.TASK_ID = #{taskId}
AND d.TEMPLATE_ID = #{templateId}
AND d.INDICATOR_ID = #{indicatorId}
AND d.ORG_ID = #{orgId}
AND d.PERIOD = #{period}
AND d.DATA_SOURCE = #{dataSource}
ORDER BY d.CREATE_TIME DESC

