mapper.select:
SELECT d.INDICATOR_ID as indicatorId, i.INDICATOR_NAME as indicatorName, COUNT(*) as dataCount, SUM(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataSum, AVG(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataAvg, MAX(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataMax, MIN(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataMin FROM TBL_REPORT_DATA d LEFT JOIN TBL_INDICATOR_INFO i ON d.INDICATOR_ID = i.INDICATOR_ID AND d.TENANT_ID = i.TENANT_ID WHERE d.TENANT_ID = #{tenantId}
AND d.TASK_ID = #{taskId}
AND d.PERIOD = #{period}
GROUP BY d.INDICATOR_ID, i.INDICATOR_NAME ORDER BY d.INDICATOR_ID

SELECT d.ORG_ID as orgId, d.ORG_ID as orgName, COUNT(*) as dataCount, SUM(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataSum, AVG(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataAvg, MAX(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataMax, MIN(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataMin FROM TBL_REPORT_DATA d WHERE d.TENANT_ID = #{tenantId}
AND d.TASK_ID = #{taskId}
AND d.PERIOD = #{period}
GROUP BY d.ORG_ID ORDER BY d.ORG_ID

SELECT d.PERIOD as period, COUNT(*) as dataCount, SUM(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataSum, AVG(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataAvg, MAX(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataMax, MIN(CAST(d.DATA_VALUE AS DECIMAL(20,2))) as dataMin FROM TBL_REPORT_DATA d WHERE d.TENANT_ID = #{tenantId}
AND d.TASK_ID = #{taskId}
AND d.INDICATOR_ID = #{indicatorId}
AND d.ORG_ID = #{orgId}
GROUP BY d.PERIOD ORDER BY d.PERIOD

SELECT current.PERIOD as period, current.INDICATOR_ID as indicatorId, i.INDICATOR_NAME as indicatorName, current.ORG_ID as orgId, CAST(current.DATA_VALUE AS DECIMAL(20,2)) as dataValue, CAST(compare.DATA_VALUE AS DECIMAL(20,2)) as compareValue, CAST(current.DATA_VALUE AS DECIMAL(20,2)) - CAST(compare.DATA_VALUE AS DECIMAL(20,2)) as growthAmount, CASE WHEN CAST(compare.DATA_VALUE AS DECIMAL(20,2)) = 0 THEN NULL ELSE ((CAST(current.DATA_VALUE AS DECIMAL(20,2)) - CAST(compare.DATA_VALUE AS DECIMAL(20,2))) / CAST(compare.DATA_VALUE AS DECIMAL(20,2))) * 100 END as growthRate FROM TBL_REPORT_DATA current LEFT JOIN TBL_REPORT_DATA compare ON current.TASK_ID = compare.TASK_ID AND current.INDICATOR_ID = compare.INDICATOR_ID AND current.ORG_ID = compare.ORG_ID AND current.TENANT_ID = compare.TENANT_ID AND compare.PERIOD = #{comparePeriod} LEFT JOIN TBL_INDICATOR_INFO i ON current.INDICATOR_ID = i.INDICATOR_ID AND current.TENANT_ID = i.TENANT_ID WHERE current.TENANT_ID = #{tenantId} AND current.PERIOD = #{currentPeriod}
AND current.TASK_ID = #{taskId}
AND current.INDICATOR_ID = #{indicatorId}
AND current.ORG_ID = #{orgId}
